/// <summary>
/// The <c>METBulkWorkflowWorkItemManager</c> class manages workflow work item actions for bulk processing.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
public class METBulkWorkflowWorkItemManager extends WorkflowWorkItemActionManager
{
    public List             workFlowWorkItemsList;
    public FormDataSource   formDatasource;
    public RefRecId         refRecId;

}

Method.Source:
/// <summary>
/// Get selected work items and process delegation.
/// </summary>
/// <param name = "_args">Argument passed.</param>
public static void main(Args _args)
{
    Common                      datasourceRecord;
    FormDataSource              dataSource = FormDataUtil::getFormDataSource(_args.record());

    // Get selected items into the list
    if (dataSource.anyMarked())
    {
        if (SalesParameters::find().METBulkWorkflowNoOfThreads == 0)
        {
            throw error("@MET:METFTIBulkWFThreadsValid");
        }
        else
        {
            // Get the references to the marked positions.
            datasourceRecord = dataSource.getFirst(true);

            METBulkWorkflowWorkItemManager workFlowWorkItemMultiDelegateManager = new METBulkWorkflowWorkItemManager();
            workFlowWorkItemMultiDelegateManager.parmArgs(_args);
            workFlowWorkItemMultiDelegateManager.parmCaller(_args.caller());
            workFlowWorkItemMultiDelegateManager.parmWorkflowWorkItemActionType(_args.parmEnum());
            workFlowWorkItemMultiDelegateManager.parmFormDatasource(dataSource);
            workFlowWorkItemMultiDelegateManager.parmCustInvoiceTableRecId(datasourceRecord.RecId);
            workFlowWorkItemMultiDelegateManager.scheduleWorkflowApprovalInBatch();
        }
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}

/// <summary>
/// Gets or sets the customer invoice table record ID.
/// </summary>
/// <param name = "_refRecId">The record ID.</param>
/// <returns>The record ID.</returns>
public RefRecId parmCustInvoiceTableRecId(RefRecId _refRecId = refRecId)
{
    refRecId = _refRecId;

    return refRecId;
}

/// <summary>
/// Gets or sets the form data source.
/// </summary>
/// <param name = "_formDatasource">The form data source.</param>
/// <returns>The form data source.</returns>
public FormDataSource parmFormDatasource(FormDataSource _formDatasource = formDatasource)
{
    formDatasource = _formDatasource;

    return formDatasource;
}

/// <summary>
/// Schedules the workflow approval in batch.
/// </summary>
public void scheduleWorkflowApprovalInBatch()
{
    this.parmWorkflowWorkItem(this.findWorkFlowWorkItemTable(this.parmCustInvoiceTableRecId()));
    this.promptWorkflowWorkItemAction();

    if (this.parmIsActionDialogClosedOK())
    {
        // Other then workflow "Approved" , workflow comment field is mandatory.
        if (this.parmWorkflowComment() == '' && this.parmWorkflowWorkItemActionType() != WorkflowWorkItemActionType::Complete)
        {
            throw Error("@MET:METFTIWFCommentValid");
        }
        else if (this.parmWorkflowWorkItemActionType() == WorkflowWorkItemActionType::Delegate)
        {
            this.validateDelegateUserIdSecurityAccess();
            METBulkWFWorkItemManagerMainController::scheduleBatch(this.parmFormDatasource(), this.parmWorkflowComment(), this.parmWorkflowWorkItemActionType(), this.parmTargetUser());
        }
        else
        {
            // Execute in batch.
            METBulkWFWorkItemManagerMainController::scheduleBatch(this.parmFormDatasource(), this.parmWorkflowComment(), this.parmWorkflowWorkItemActionType(), this.parmTargetUser());
        }
    }
}

/// <summary>
/// Finds the workflow work item table record by record ID.
/// </summary>
/// <param name = "_recId">The record ID.</param>
/// <returns>The workflow work item table record.</returns>
public WorkflowWorkItemTable findWorkFlowWorkItemTable(RefRecId _recId)
{
    WorkflowWorkItemTable WorkflowWorkItemTable;

    select firstonly WorkflowWorkItemTable
        where (workflowWorkItemTable.Type    == WorkflowWorkItemType::WorkItem 
        ||  workflowWorkItemTable.Type       == WorkflowWorkItemType::Return)
        &&  workflowWorkItemTable.Status     == WorkflowWorkItemStatus::Pending
        &&  WorkflowWorkItemTable.RefTableId == tableNum(CustInvoiceTable)
        &&  WorkflowWorkItemTable.RefRecId   == _recId;

    return WorkflowWorkItemTable;
}

/// <summary>
/// Validate the user id with security access.
/// </summary>
[SuppressBPWarning('TwCParametersMustBeValidated', 'Parameter required by the event interface.')]
public void validateDelegateUserIdSecurityAccess()
{
    UserId          user = this.parmTargetUser();
    boolean         retActionMenu, retDisplayMenu = false;
    UserInfo        userInfo;
    container       result;

    select firstonly Enable, ObjectId,RecId from userInfo 
        where userInfo.Id == user;

    if (userInfo && userInfo.Enable)
    {
        try
        {
            // impersonate as the batchExecutor to make sure the datawriting batch executor is set to the value in batchExecutorUserId
            RunAsPermission permission = new RunAsPermission(user);
            permission.assert();
            result = runAs(user,
                      classnum(METBulkWorkflowWorkItemManager),
                      staticMethodStr(METBulkWorkflowWorkItemManager, assertAsUser),
                      [userInfo.RecId]);
        }
        finally
        {
            CodeAccessPermission::revertAssert();
        }

        retActionMenu  = conPeek(result, 1);
        retDisplayMenu = conPeek(result, 2);

        if (!retActionMenu || !retDisplayMenu)
        {
            setPrefix(classStr(SysWorkflowWorkItem) + '-' + staticMethodStr(SysWorkflowWorkItem, delegate));
            throw error(strFmt("@SYS109561", userInfo.ObjectId));
        }
    }
}

/// <summary>
/// Verify current user id having proper security access or not.
/// </summary>
/// <param name = "_args">Caller args.</param>
/// <returns>Return true if success; else false.</returns>
private server static container assertAsUser(
    container _args)
{
    SecurityRights  securityRights;
    boolean         retActionMenu, retDisplayMenu = false;

    if (conLen(_args) > 0)
    {
        securityRights = SecurityRights::construct();
        retActionMenu  = securityRights.menuItemAccessRight(SecurableType::MenuItemAction, menuItemActionStr(CustFreeInvoiceApprovalApprove), '') > AccessRight::NoAccess;
        retDisplayMenu = securityRights.menuItemAccessRight(SecurableType::MenuItemDisplay, menuItemDisplayStr(CustFreeInvoicedetails), '') > AccessRight::NoAccess;
    }

    return [retActionMenu, retDisplayMenu];
}
